import itertools, json
jobs="ABCDE"
slot={"A":[10,7,11,4,4],"B":[3,1,1,4,8],"C":[5,4,5,6,2],"D":[3,3,7,1,11],"E":[10,9,10,1,9]}
transfer=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(p):
    return sum(slot[j][i] for i,j in enumerate(p))+sum(transfer[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
    pos={j:p.index(j)+1 for j in jobs}
    if pos["A"]>=pos["D"]: return False
    return {"rain":pos["C"]!=5 and pos["A"]!=1,
            "road":pos["B"]!=1 and pos["C"]!=2,
            "lift":pos["D"]!=5 and pos["B"]!=5}[s]
def penalty(p,s):
    pos={j:p.index(j)+1 for j in jobs}
    return {"rain":8*max(0,pos["E"]-1),"road":5*max(0,pos["D"]-3),"lift":5*max(0,pos["E"]-2)}[s]
perms=list(itertools.permutations(jobs))
records=[]
for p in perms:
    if p.index("A")>p.index("D"): continue
    neighbors=[(p,0)]
    for i,j in itertools.combinations(range(5),2):
        q=list(p); q[i],q[j]=q[j],q[i]
        neighbors.append((tuple(q),1))
    best={}
    for s in ("rain","road","lift"):
        vals=[(nominal(q)+penalty(q,s)+fee,"".join(q)) for q,fee in neighbors if legal(q,s)]
        if not vals: break
        best[s]=min(vals)
    if len(best)==3:
        records.append((nominal(p)+max(c for c,q in best.values()),"".join(p),best))
records.sort()
score,p,best=records[0]
out={"roster":p,"score":score,"repairs":{s:q for s,(c,q) in best.items()},"repair_costs":{s:c for s,(c,q) in best.items()},"feasible_count":len(records),"next_score":min(r[0] for r in records if r[0]>score)}
# Independent neighborhood generation: identity or exactly two mismatches.
checked=[]
for pub in perms:
    if pub.index("A")>pub.index("D"): continue
    minima=[]
    for s in ("rain","road","lift"):
        costs=[]
        for q in perms:
            d=sum(a!=b for a,b in zip(pub,q))
            if d not in (0,2) or not legal(q,s): continue
            costs.append(nominal(q)+penalty(q,s)+(d==2))
        if not costs: break
        minima.append(min(costs))
    if len(minima)==3: checked.append((nominal(pub)+max(minima),"".join(pub)))
assert sorted(checked)==sorted((r[0],r[1]) for r in records)
print(json.dumps(out))
print("published nominal",nominal(tuple(p)),"optimal ties",sum(r[0]==score for r in records),"verified publications",len(checked))

