import itertools,json
pub="EABDC"
jobs="ABCDE"
sc={"A":[10,7,11,4,4],"B":[3,1,1,4,8],"C":[5,4,5,6,2],"D":[3,3,7,1,11],"E":[10,9,10,1,9]}
tr=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def distance(q):
    perm=[pub.index(x) for x in q]
    seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i); i=perm[i]
    return 5-cycles
def nominal(q):
    return sum(sc[x][i] for i,x in enumerate(q))+sum(tr[a][jobs.index(b)] for a,b in zip(q,q[1:]))
classes={d:[] for d in range(3)}
for p in itertools.permutations(jobs):
    q="".join(p); d=distance(q)
    if d>2: continue
    if q.index("A")>q.index("D") or q[4]=="C" or q[0] in "AE": continue
    cost=nominal(q)+8*q.index("E")+d+(10 if d==2 else 0)
    classes[d].append((cost,q))
best=min(x for v in classes.values() for x in v)
# Independently verify exchange distances by breadth-first expansion.
dist={pub:0}
front={pub}
for depth in (1,2):
    nxt=set()
    for q in front:
        for i,j in itertools.combinations(range(5),2):
            r=list(q); r[i],r[j]=r[j],r[i]; r="".join(r)
            if r not in dist: dist[r]=depth; nxt.add(r)
    front=nxt
assert all(distance(q)==d for q,d in dist.items())
assert all((distance("".join(q))<=2)==("".join(q) in dist) for q in itertools.permutations(jobs))
print(json.dumps({"roster":best[1],"score":best[0],"best_by_swaps":{str(d):min(v)[0] if v else None for d,v in classes.items()},"feasible_by_swaps":{str(d):len(v) for d,v in classes.items()}}))
print("best breakdown", nominal(best[1]),8*best[1].index("E"),distance(best[1]))

